      SUBROUTINE BENDCC     CALCULATES FIRST-ORDER TRANSFER MATRIX FOR A BENDING MAGNETC      INCLUDE 'BETAC.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4B.CIN'      INCLUDE 'ELM4D.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'R.CIN'      INCLUDE 'TERMS.CIN'      INCLUDE 'WMN.CIN'CC     LOCAL VARIABLESC      REAL  CXY, CYX, SKX, SKY, WM2NCC---------------------------------------------------------------C     FIRST-ORDER TRANSFER MATRIXC      JQUAD = 1      RH = 1.0 + RMPS      H = RH*H0      WMN = (1.0 - NB) + RMPS*(2.0 - NB)      IF (WMN .EQ. 0.0) THEN        WRITE (NOUT,9101) 9101   FORMAT (' N = 1.0 DOES NOT WORK WITH EXISTING EXPRESSIONS ',     1          'FOR MATRIX ELEMENTS, TRY RESETTING TO 1.0001')        FLUSHL = .TRUE.        GO TO 500      ENDIF      KQ2 = H0**2*WMN      KX2 = KQ2      CALL FOCUS      CX = R(1,1)      SX = R(1,2)      SKX = - R(2,1)      JQUAD = 3      KQ2 = H0**2*RH*NB      KY2 = KQ2      CALL FOCUS      CY = R(3,3)      SY = R(3,4)      SKY = - R(4,3)      IF (CX .GT. 0.5) DISN = SX**2/(1.0 + CX)      IF (CX .LE. 0.5) DISN = (1.0 - CX)/(WMN*H0**2)      DISP = H*DISN      R(1,6) = DISP      R(5,2) = - H0*DISN      DDISP = H*SX      R(2,6) = DDISP      R(5,1) = - H0*SX      R56 = - RH*(L - SX)/WMN      IF (SM .NE. 0.0 .AND. RI .NE. 0.0) R56 = R56  + L/GAMMA**2      R(5,6) = R56CC     TERMS USED FOR HIGHER ORDER OR OFF-AXIS EXPANSION ORC     NON-MIDPLANE SYMMETRIC FIELD COMPONENTSC      IF (CY .GT. 0.5) DSVN = SY**2/(1.0 + CY)      IF (CY .LE. 0.5) DSVN = (1.0 - CY)/(NB*H*H0)      XPND = ABS(SQRT(ABS(WMN))*H0*L) .LT. 0.01      IF (XPND) THEN        SMLCX = 1.0/3.0*WMN*H0**2*L**3 - 1.0/30.0*WMN**2*H0**4*L**5      ELSE        SMLCX = SX - L*CX      ENDIFCC     OFF-AXIS EXPANSION OR NON-MIDPLANE-SYMMETRIC FIELD COMPONENTSC      IF (RMPS .EQ. 0.0 .AND. (RNMS .EQ. 0.0 .OR.     1   (VRN .EQ. 0.0 .AND. NPN .EQ. 0.0 .AND. BDBP .EQ. 0.0)))     2   GO TO 500      IF (RMPS .NE. 0.0 .OR. (RNMS .NE. 0.0 .AND. VRN .NE. 0.0)) THEN        DCOV = .TRUE.        IF (BAX) R1P = .TRUE.      ENDIF      HEX = H0*RMPS      VR = RNMS*VRN      NPR = NPN*RNMS      COD(1) = - RMPS*H0*DISN      COD(2) = - RMPS*H0*SX      COD(3) = VR*H0*DSVN      COD(4) = VR*H0*SY      COD(5) = 0.0      COD(6) = 0.0      IF (NORD1 .LT. 1) GO TO 500      CXY = (VR - NPR)      CYX = RH*(NPR - 2.0*VR)      WM2N = 1.0 - 2.0*NB + RMPS*(2.0 - 2.0*NB)      IF (WM2N .EQ. 0.0) THEN        WRITE (NOUT,9100) 9100   FORMAT (' N = 0.5 DOES NOT WORK WITH VIOLATION OF MIDPLANE',     1          ' SYMMETRY, TRY RESETTING TO .5001')        FLUSHL = .TRUE.        GO TO 500      ENDIF      R(1,3) = CXY*(CY - CX)/WM2N      R(1,4) = CXY*(SY - SX)/WM2N      R(2,3) = CXY*(SKX - SKY)/WM2N      R(2,4) = CXY*(CY - CX)/WM2N      R(3,1) = CYX*(CX - CY)/WM2N      R(3,2) = CYX*(SX - SY)/WM2N      R(4,1) = CYX*(SKY - SKX)/WM2N      R(4,2) = CYX*(CX - CY)/WM2N      R(3,6) = - VR*H0*DSVN     1       + H0*CYX*(DISN - DSVN)/WM2N      R(4,6) = - VR*H0*SY     1       + H0*CYX*(SX - SY)/WM2N      R(5,3) = H0*CXY*(SX - SY)/WM2N      R(5,4) = H0*CXY*(DISN - DSVN)/WM2NC  500 RETURN      END